import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"需","description":"焦氏易林注 - 需","frontmatter":{"title":"需","description":"焦氏易林注 - 需"},"headers":[],"relativePath":"zh/classics/jiaoyilin/005.md","filePath":"zh/classics/jiaoyilin/005.md"}'),l={name:"zh/classics/jiaoyilin/005.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="需" tabindex="-1">需 <a class="header-anchor" href="#需" aria-label="Permalink to “需”">​</a></h1><h3 id="需-1" tabindex="-1">需 <a class="header-anchor" href="#需-1" aria-label="Permalink to “需”">​</a></h3><h3 id="需之乾" tabindex="-1">需之乾 <a class="header-anchor" href="#需之乾" aria-label="Permalink to “需之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>火滅復息，君明其德。仁人可遇，身受利福。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《需》象。中爻離火，上臨坎水，故火滅。然《革》彖曰水火相息，故曰火滅復息。乾為君、為德、為仁人。離為明，伏坤為身。○福，汲古作祿，依宋元本。</p><h3 id="需之坤" tabindex="-1">需之坤 <a class="header-anchor" href="#需之坤" aria-label="Permalink to “需之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>溫山松柏，常茂不落。鸞鳳所庇，得其歡樂。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍用《需》象。乾為山，離為火，故曰溫山。坎為木、為堅，故曰松柏、故曰不落。離為文章，故曰鸞鳳。互兌為悅，故歡樂。</p><h3 id="需之屯" tabindex="-1">需之屯 <a class="header-anchor" href="#需之屯" aria-label="Permalink to “需之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>西誅不服，恃強負力。倍道超敵，師徒敗覆。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎位西，坤殺，故曰西誅。艮為負、為堅，故曰恃強負力。艮為道，震為大塗，故曰倍道。震為超，正反艮震，故曰敵。坤為師徒、為喪，故敗覆。丁晏雲：「《史記》：「項梁西擊秦，屢敗之，有驕色，後敗死定陶」，林辭似用其事。○西，汲古作四，服作復，均非，從宋元本。○坎西之證。</p><h3 id="需之蒙" tabindex="-1">需之蒙 <a class="header-anchor" href="#需之蒙" aria-label="Permalink to “需之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>三塗五嶽，陽城太室。神明所伏，獨無兵革。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>丁雲：《左傳昭四年》「四岳三塗，陽城太室，九州島之險」，註：皆山名。正反艮，故山多，震為神明，坎為伏，艮為兵刃、為膚革，坤虛，故無。○所伏，從宋元本，汲古作之保。</p><h3 id="需之需" tabindex="-1">需之需 <a class="header-anchor" href="#需之需" aria-label="Permalink to “需之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>久旱三年，草木不生。粢盛空乏，無以供靈。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。離火艮火，故曰久旱。離數三，坤為年，故曰三年。震為生、為草木，震覆，故不生。震為粢、為簠簋，故為盛。坤虛故空乏。</p><h3 id="需之訟" tabindex="-1">需之訟 <a class="header-anchor" href="#需之訟" aria-label="Permalink to “需之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>三牛生狗，以戌為母。荊夷上侵，姬伯出走。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之「震」。三牛，從汲古本，宋元本作二牛。離牛坤牛，數二，故曰二牛。象亦合。</p><h3 id="需之師" tabindex="-1">需之師 <a class="header-anchor" href="#需之師" aria-label="Permalink to “需之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>鳧游江海，沒行千里。以為死亡，復見空桑。長生樂鄉。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為鳧、為游行，坤為江海、為沒、為千里、為死亡。二上體復震為桑，坤虛，故曰復見空桑。震為生、為樂，坤為鄉，《呂氏春秋》：「伊尹生空桑。」○沒、桑、長生樂鄉，均依汲古，宋元本作役、作素、作長主凶憂。</p><h3 id="需之比" tabindex="-1">需之比 <a class="header-anchor" href="#需之比" aria-label="Permalink to “需之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>太乙駕騮，從天上求。徵召叔季，封為魯侯。無有凶憂。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤乙艮星，故曰太乙。坤為馬，五居坤上，故曰駕騮。艮為天、為求、為叔季，伏兌為徵召、為魯。坎為合、為封，坤為凶坎、為憂，坤虛故無。○求，宋本、汲古作來，召訛君，依元本。</p><h3 id="需之小畜" tabindex="-1">需之小畜 <a class="header-anchor" href="#需之小畜" aria-label="Permalink to “需之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>紝績獨處，寡處無夫。陰陽失志，為人僕使。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為紝績、為獨、為寡，震為夫，震伏，故無夫。伏坎為志，坤為失，艮為僕使。○志，從汲古，宋元本作忌。</p><h3 id="需之履" tabindex="-1">需之履 <a class="header-anchor" href="#需之履" aria-label="Permalink to “需之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>兵徵大宛，北出玉門，與胡寇戰。平城道西，七日絕糧，身幾不全。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。與《屯》同象，解見《屯》林。</p><h3 id="需之泰" tabindex="-1">需之泰 <a class="header-anchor" href="#需之泰" aria-label="Permalink to “需之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>楚靈暴虐，罷極民力。禍起乾溪，棄疾作毒。扶伏奔逃，死申亥室。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為木、為楚，楚，叢木也，為神、為靈、為暴。坤為害、為虐，坤役萬物故罷極。坤為民、為禍，兌為溪，下乾，故曰乾溪。坤為疾、為毒。棄疾，靈王弟。艮為扶、為伏，扶伏，匍匐也，言匍匐而逃也。震為奔逃，坤死。坤後天位申，消息卦居亥，故死申亥。伏艮為室。○極，從宋元本，汲古作及，非。伏，從元本，宋本、汲古作仗，非。死申亥室，宋本、汲古作「身死亥室」，非，依元本。申亥者，楚臣。《左傳昭十三年》：「楚靈王暴虐，師潰於乾溪，王遂縊於羋尹申亥氏」，申亥，羋尹無宇之子也。妄者臆改申為身耳。</p><h3 id="需之否" tabindex="-1">需之否 <a class="header-anchor" href="#需之否" aria-label="Permalink to “需之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>雌單獨居，歸其本巢。毛羽憔悴，志如死灰。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為雌、為寡，艮為居、為巢，伏震為歸，故曰歸其本巢。巽為寡髪，故毛羽憔悴。坤為死、為志，灰，蓋艮象。</p><h3 id="需之同人" tabindex="-1">需之同人 <a class="header-anchor" href="#需之同人" aria-label="Permalink to “需之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>兩矛相刺，勇力鈞敵。交綏結和，不破不缺。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>兌為斧、為矛，下離兩兌相對，故曰兩矛相刺。乾健，故曰勇。伏坎為和，巽為退。交綏，退軍名，見《左傳》文十二年交綏註。坎為破、為缺，坎伏故否。○汲古綏訛援，依宋元本。</p><h3 id="需之大有" tabindex="-1">需之大有 <a class="header-anchor" href="#需之大有" aria-label="Permalink to “需之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>乘船濟渡，載水逢火。賴幸免禍，蒙我生全。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤虛為船，坎為水，坤為載，故曰載水。互艮為火，故曰逢火。坤為禍，乾為幸，坤為我，乾為生。○幸，從宋本，汲古作行。</p><h3 id="需之謙" tabindex="-1">需之謙 <a class="header-anchor" href="#需之謙" aria-label="Permalink to “需之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>喪寵益尤，政傾家覆。我宗失國，秦滅周室。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為寵，坤為喪、為尤、為政，艮為家，坎陷，故傾覆。震為宗，坤為我、為國、為失，坎位西，故曰秦。震為周，艮室坤喪，故滅。○益，宋元本作溢，依汲古。</p><h3 id="需之豫" tabindex="-1">需之豫 <a class="header-anchor" href="#需之豫" aria-label="Permalink to “需之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>冬無藏冰，春陽不通。陰流為賊，國被其殃。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為冬、為冰，坤為藏，在下故不藏。震為春陽，坎陷，故不通。坤為陰，坎為賊，坤為國、為殃。○陽，從宋本，汲古作江，非。</p><h3 id="需之隨" tabindex="-1">需之隨 <a class="header-anchor" href="#需之隨" aria-label="Permalink to “需之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>田鼠野雞，意常欲逃。拘制籠檻，不得動搖。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為鼠，巽為雞，艮為田野，故曰田鼠野雞。震為逃，艮為籠檻、為拘，故不得動搖。○常，從宋本，汲古及俗本皆誤當。</p><h3 id="需之蠱" tabindex="-1">需之蠱 <a class="header-anchor" href="#需之蠱" aria-label="Permalink to “需之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>佩玉橤兮，無所系之。旨酒一盛，莫與笑語。孤寡獨特，常愁憂苦。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互震為玉、為華、為橤，艮為佩，巽為系，兌決，故無系。互大坎為酒，震為盛，坎數一，故曰一盛。震為笑語，巽寡，故無與。艮陽在上，故孤，巽寡震陽在下為獨，兌為特，大坎為憂愁。凡六子《易林》皆有鰥寡孤獨象。○橤，從宋本，汲古作藻，非。《左傳哀十三年》：「佩玉橤兮，餘無所系之，旨酒一盛兮，餘與褐之父睨之」，林所本也。</p><h3 id="需之臨" tabindex="-1">需之臨 <a class="header-anchor" href="#需之臨" aria-label="Permalink to “需之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>沒游源口，求鮫為寶。家危自懼，復出生道。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>兌為源、為口，坤為水，震為游，故曰沒游源口。坤為魚、為鮫，震為玉、為寶，伏艮為求，故曰求鮫為寶。《述異記》：「鮫人居水中如魚，不廢機織，眼泣成珠」，故曰求鮫為寶。艮為家，艮覆，故家危。二至上體復震為出、為生、為道，故曰復出生道。○寶，從宋本，汲古作室，非。寶與道韻。</p><h3 id="需之觀" tabindex="-1">需之觀 <a class="header-anchor" href="#需之觀" aria-label="Permalink to “需之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>河水孔穴，壞敗我室。水深無岸，魚鱉傾倒。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為河水，艮為孔穴，巽為敗壞，艮為室，坤為我，重坤，故曰水深。艮為岸，巽敝，故無岸。艮為鱉，坤為魚，巽漏，故傾倒。</p><h3 id="需之噬嗑" tabindex="-1">需之噬嗑 <a class="header-anchor" href="#需之噬嗑" aria-label="Permalink to “需之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>教羊牧兔，使魚捕鼠。任非其人，費日無功。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>伏兌為羊，巽為魚，震為兔，艮為鼠，巽為命，故曰教、曰使。艮手為牧、為捕，震為人，上離為日，坎失，故失任、故無功。○捕鼠，從宋本，元本作相捕，非。人，古音仍，與功韻。語本《淮南子主術訓》。</p><h3 id="需之賁" tabindex="-1">需之賁 <a class="header-anchor" href="#需之賁" aria-label="Permalink to “需之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>升戶入室，就溫燠食。冰凍北陸，不能相賊。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為戶、為室，震為升，伏巽為入，故曰升戶入室。離火為溫，震為缶，在離上有若燠食，坎為食也。坎為冰、為凍、為北陸、為賊，震樂，故不賊。○燠，從宋元本，汲古等本作暖，非。冰，依宋本，元本作水。</p><h3 id="需之剝" tabindex="-1">需之剝 <a class="header-anchor" href="#需之剝" aria-label="Permalink to “需之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>孤竹之墟，老婦亡夫。傷於蒺藜，不見少妻。東郭棠薑，武氏破亡。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為寡，坤虛，故為竹，坤為墟，故曰孤竹之墟。伏兌為老婦，震為夫，震覆坤喪，故曰亡夫。三四句用《遇》卦「需」象。坎為蒺藜，兌為少妻，坎伏，故不見，艮為城郭，震為武，震覆，故武氏破亡。武子者，崔杼，娶東郭偃之姊、棠公之妻，棠公死，武子弔，見棠薑而美之，遂娶之。事見《左傳襄二十五年》。○老，汲古作失，《大過》以兌為老婦，故《易林》本之，遇兌即言老婦，此於經義所關至巨，後人不知老婦指兌，於是說《大過》而誤，《易林》老婦亦不知所謂。</p><h3 id="需之復" tabindex="-1">需之復 <a class="header-anchor" href="#需之復" aria-label="Permalink to “需之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>凶憂災殃，日益明彰。福不可釐，三卻夷傷。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為凶憂災殃。震為明彰。坤禍，故無福。釐，予也。《詩大雅》：「釐爾士女」是也。震數三，三卻，卻錡、卻釐、卻至。伏巽為隙，坤喪故夷。○憂，汲古作禍，晉殺三卻在成七年。</p><h3 id="需之無妄" tabindex="-1">需之無妄 <a class="header-anchor" href="#需之無妄" aria-label="Permalink to “需之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>載璧秉圭，請命於河。周公作誓，沖人瘳愈。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為璧、為圭、為載，艮手為秉，故曰載璧秉圭。巽為命，震為請，上乾為河，故請命於河。震為周、為作、為誓、為沖人、為樂，故瘳愈。《史記魯世家》：「成王病，周公為自揃其蚤沈之河，成王病果愈」，沖人，成王也。○作誓，從宋元本，汲古作克敏。按：《金縢》作植璧秉圭，後有此林亦作植璧，然各本皆作載，故依之。</p><h3 id="需之大畜" tabindex="-1">需之大畜 <a class="header-anchor" href="#需之大畜" aria-label="Permalink to “需之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛鵲舉，照臨東海。尨降庭堅，為陶叔後。封圻英六，履福綏厚。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥鵲，震為飛舉。乾為海，納甲，故曰東海。震多毛，尨，多毛犬也。艮為庭、為堅，艮為火、為陶，故曰陶叔。震為後、為英，乾數六，艮為封圻，故曰封圻英六。庭堅，皋陶字，言皋陶之後封在英、六二國也，見《史記陳世家》，又《左傳》文五年，楚人滅六、滅蓼。臧文仲曰「皋陶庭堅不祀，忽諸」，又《楚世家》「成王二十六年滅英」，張守節疑英即蓼，非。據《杞世家》，英亦皋陶後。○封圻，從宋元本，汲古作圭祈，非。六，汲古等本皆作雄，惟宋元本作六。飛，依汲古，宋元皆作升。</p><h3 id="需之頤" tabindex="-1">需之頤 <a class="header-anchor" href="#需之頤" aria-label="Permalink to “需之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>危坐至暮，請求不得。膏澤不降，政戾民忒。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為坐，坤暮。艮為請求，坤虛，故不得。上伏兌為膏澤，艮止故不降。坤為政、為民，坤凶，故曰戾、曰忒。○忒，汲古作惑，依宋元本。</p><h3 id="需之大過" tabindex="-1">需之大過 <a class="header-anchor" href="#需之大過" aria-label="Permalink to “需之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>宜昌娶婦，東家歌舞。宴樂有緒，長安嘉喜。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。巽為婦，震為娶、為東、為歌舞，艮為家，故曰東家歌舞。巽為緒，震為嘉樂。○安，宋元本作樂，依汲古。</p><h3 id="需之坎" tabindex="-1">需之坎 <a class="header-anchor" href="#需之坎" aria-label="Permalink to “需之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>鑿井求玉，非卞氏寶。名困身辱，勞無所得。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮手為鑿、為求，坎為井，震為玉、為寶，艮為身名，坎為困，楚卞和玉最良，然求之於井非其地。坎為勞、為失，故無得。</p><h3 id="需之離" tabindex="-1">需之離 <a class="header-anchor" href="#需之離" aria-label="Permalink to “需之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復反其室。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。震為鵠、為東，離文為鳳，震為羽翼，艮手為理，互巽，故曰順理。震為出，艮為次，離為日，艮止，故須日。艮為邑，坎北，故曰北邑，艮止故留。震為復，坎室。○出次須日，中留北邑。從宋元本，汲古作「出次日中，須留北邑」，非。因翼日室為韻，妄人盲改，韻不協矣。</p><h3 id="需之咸" tabindex="-1">需之咸 <a class="header-anchor" href="#需之咸" aria-label="Permalink to “需之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>早霜晚雪，傷害禾麥。損功棄力，飢無所食。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>乾為冰、為霜雪，巽為禾麥，兌為傷、為害、為損棄，乾為功，兌為食，伏坤為飢，故無所食。</p><h3 id="需之恒" tabindex="-1">需之恒 <a class="header-anchor" href="#需之恒" aria-label="Permalink to “需之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>蝙裊生子，深目黑醜。雖飾相就，眾人莫取。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>蝙裊，即蝙蝠。《爾雅》註：「齊人謂之蝙裊」。巽為蟲，震為生、為子，伏大離，故曰深目。伏坤為黑、為醜、為文飾、為眾，震為人，艮手為取，艮覆，故莫取。○蝙●，從元本，宋本作蝙螺，汲古及常本作蝠螺，皆非。</p><h3 id="需之遯" tabindex="-1">需之遯 <a class="header-anchor" href="#需之遯" aria-label="Permalink to “需之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>去如飛鴻，避凶直東。遂得全脫，與福相逢。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮陽在上為飛，艮為鳥，故為鴻，巽伏，故曰避凶。伏震為東、為脫，乾為福。○直，宋本作且，依元本。</p><h3 id="需之大壯" tabindex="-1">需之大壯 <a class="header-anchor" href="#需之大壯" aria-label="Permalink to “需之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>婚姻合配，同枕共牢。以降休嘉，子孫封侯。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>此合對象。言震巽為婚姻、為合配。艮木為枕，震為盆、為牢，《史記平準書》「官與牢盆」，樂彥雲：「牢乃盆名」，《禮記昏義》：「共牢而食」註，共牢者，共食一牲也。此則以震盆為象，震為休嘉、為子，兌為孫，震為諸侯。</p><h3 id="需之晉" tabindex="-1">需之晉 <a class="header-anchor" href="#需之晉" aria-label="Permalink to “需之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>咸陽辰己，長安戌亥。邱陵生止，非魚䲡市。不可避阻，終無悔咎。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>伏乾為陽。消息卦乾居辰己，坤為安，消息卦居戌亥，互艮為邱陵、為止，坤為魚暎言邱陵之地非魚市也。坎為阻。○避，依汲古，宋元本作辭。</p><h3 id="需之明夷" tabindex="-1">需之明夷 <a class="header-anchor" href="#需之明夷" aria-label="Permalink to “需之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>螟蟲為賊，害我五穀。簟笥空虛，家無所食。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>伏巽為螟。螟，食苗心蟲。坎為賊，坤為害，互震為谷，坤數五，故曰五穀。震為簟笥，坤為空虛，故無所食。○笥，依汲古，宋元本作食。</p><h3 id="需之家人" tabindex="-1">需之家人 <a class="header-anchor" href="#需之家人" aria-label="Permalink to “需之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>蒙恩拜德，東歸吾國。慷慨宴笑，歡樂有福。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>象多未詳。祇東歸及宴笑歡樂知用伏象。○蒙，依汲古，宋元本作謀。</p><h3 id="需之睽" tabindex="-1">需之睽 <a class="header-anchor" href="#需之睽" aria-label="Permalink to “需之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>齎貝贖狸，不聽我辭。繫於虎鬚，牽不得求。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>伏《蹇》。艮為齎，離為貝，艮為狸，震為辭，震覆，故不聽。坎為聽也。艮為虎、為須、為牽，艮止，故不來。</p><h3 id="需之蹇" tabindex="-1">需之蹇 <a class="header-anchor" href="#需之蹇" aria-label="Permalink to “需之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>比目附翼，歡樂相得。行止集周，終不離忒。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>伏重離故曰比目。兌悅為歡樂，艮為止。○集周，依宋元本，《詩》：「集於道周」是也。汲古作同。</p><h3 id="需之解" tabindex="-1">需之解 <a class="header-anchor" href="#需之解" aria-label="Permalink to “需之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>一指食肉，口無所得。染其鼎鼐，舌饞於腹。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎為肉，數一，故曰一指食肉。一，或為以之訛字，不敢定也。震為口，在外，故無得。震為鼎鼐，故染指於鼎鼐也。離為腹。此仍用子公染指於鼎事，詳《蒙》之「萃」。○一，應作以。</p><h3 id="需之損" tabindex="-1">需之損 <a class="header-anchor" href="#需之損" aria-label="Permalink to “需之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>曳綸江湖，釣掛魴鯉。王孫利得，以享仲友。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>通《咸》。巽為綸，艮手為曳。坤為江湖，故曰曳綸江湖。艮為釣、為掛，坤為魚，震為王，艮為孫，故曰王孫。巽為利，兌為友，伏大坎為仲。○江湖，從元本，宋作江海，汲古作汀洲。王孫利得，汲古作「公孫得利」，依宋元本。</p><h3 id="需之益" tabindex="-1">需之益 <a class="header-anchor" href="#需之益" aria-label="Permalink to “需之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>商紂牧野，顛敗所在。賦斂重數，黎元愁苦。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為惡，故曰商紂。坤為野、為養、為牧，故曰牧野。坤喪，故顛敗，坤為藏，故為賦斂。坤為重，故曰重數。坤為民、為黑，又艮黔震蒼，故曰黎元。伏大坎為愁苦。</p><h3 id="需之夬" tabindex="-1">需之夬 <a class="header-anchor" href="#需之夬" aria-label="Permalink to “需之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>北辰紫宮，衣冠立中。含和建德，常受天福。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮為星，坤北，故曰北辰。艮為宮、為冠，乾為衣，兌為和，乾為天、為福。○立中，依宋本，毛本、元作中立。</p><h3 id="需之姤" tabindex="-1">需之姤 <a class="header-anchor" href="#需之姤" aria-label="Permalink to “需之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>輕戰尚勇，不知兵權。為敵所制，從師北奔。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為勇、為戰，坤為兵，巽為權，坤迷，故不知兵權。震為徵、為奔，坤為師、為北，故曰從師北奔。○從，依宋元本，汲古作徵。</p><h3 id="需之萃" tabindex="-1">需之萃 <a class="header-anchor" href="#需之萃" aria-label="Permalink to “需之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>大口宣唇，神使伸言。黃龍景星，出應德門。興福上堂，天下安昌。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>兌為口、為唇，巽白為宣，伏震為神、為伸。兌為言，伏震為黃、為龍。艮為星、為明，故曰景星。艮為門堂。○唇，從宋元本，汲古作舌。伸，宋元本作仲，依汲古。興、堂，從汲古，宋元本作與、作天，非。</p><h3 id="需之升" tabindex="-1">需之升 <a class="header-anchor" href="#需之升" aria-label="Permalink to “需之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>凶子禍孫，仗劍出門。凶訟歡囂，驚駭我家。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為凶禍，震為子孫，伏艮為匕、為劍。坤為門戶，震出，故曰出門。初至四正反兩兌口相背，故曰凶訟歡囂。震為驚駭，坤為我，艮為家，艮反，故驚駭我家。○仗，依元本，宋毛作把。</p><h3 id="需之困" tabindex="-1">需之困 <a class="header-anchor" href="#需之困" aria-label="Permalink to “需之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>祝伯善言，能事鬼神。辭祈萬歲，使君延年。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>三至上正反兌口，故善言，易所謂尚口也，故曰祝伯。祝史以口舌為用。伏震為伯，坎為鬼，伏震為神、為辭、為歲年、為萬、為君，辭猶拜表拜書。○辭祈，從宋元本，汲古本、局本作拜辭，非。</p><h3 id="需之井" tabindex="-1">需之井 <a class="header-anchor" href="#需之井" aria-label="Permalink to “需之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>圭璧琮璋，執贄見王。百裡寧戚，應聘齊秦。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏震為玉、為王，伏艮為手、為執，震為百裡，坎為憂戚。巽為齊，兌為秦，百裡奚用於秦穆、寧戚以飯牛歌乾齊桓也。</p><h3 id="需之革" tabindex="-1">需之革 <a class="header-anchor" href="#需之革" aria-label="Permalink to “需之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>昧旦乘車，履危蹈溝。亡失裙襦，摧折兩軸。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為昧旦、為乘、為車、為履、為蹈，坎險為溝瀆，震上坎下，故履危蹈溝。坤為亡失，震為裙襦，坎折坤，坤數二，故曰兩軸。坤為軸也。○震為襦證。</p><h3 id="需之鼎" tabindex="-1">需之鼎 <a class="header-anchor" href="#需之鼎" aria-label="Permalink to “需之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>膠著木連，不出牛欄。斯饗羔羊，家室相安。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坎為膠，震艮坎皆為木，故曰木連。又屯初至五正反兩震相合，亦有木連象。震為出，坤為牛，艮為欄，艮止，故不出。本卦兌為羔羊、為食，故曰饗。艮為家室、為安。○木連，從宋本，汲古及常本皆訛未通，將卦象妙用全失。</p><h3 id="需之震" tabindex="-1">需之震 <a class="header-anchor" href="#需之震" aria-label="Permalink to “需之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>卷領遯世，仁德不舍。三聖攸同，周國茂興。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為領，坎伏，故曰卷領、曰遁世。震為仁德，艮止，故不舍，舍，發也。坎為聖，震數三，故曰三聖。艮為國，震為周、為興，故曰周國茂興。○領，依宋元本，汲古作舌。國，依元本，宋、汲古作家。</p><h3 id="需之艮" tabindex="-1">需之艮 <a class="header-anchor" href="#需之艮" aria-label="Permalink to “需之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>黍稷苗稻，垂秀方造。中旱不雨，傷風枯槁。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為禾苗、為秀、為造，造，作也。坎為中、為雨，艮火故旱、故不雨。伏巽為風，離為枯槁。○苗稻，從宋本，汲古作禾稼，韻不協，非。</p><h3 id="需之漸" tabindex="-1">需之漸 <a class="header-anchor" href="#需之漸" aria-label="Permalink to “需之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>冠帶南游，與福喜逢。期於嘉貞，拜為公卿。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮冠巽帶，離南。伏震為福，喜為嘉貞者，卜問。《周禮》：「天府秀冬陳玉以貞來歲之美惡」是也。艮手為拜，艮為官，故為公卿。○貞，汲古作徵，依宋本。</p><h3 id="需之歸妹" tabindex="-1">需之歸妹 <a class="header-anchor" href="#需之歸妹" aria-label="Permalink to “需之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>一巢九子，同公共母。柔順利貞，出入不殆，福祿所在。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>離為巢，坎數一，故曰一巢。震為子，數九，故曰九子。震為公，伏巽為母，故曰同公共母。震出巽入，震為勇往，故不殆，震又為福祿也。</p><h3 id="需之豐" tabindex="-1">需之豐 <a class="header-anchor" href="#需之豐" aria-label="Permalink to “需之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>韓氏長女，嫁於東海。宜家宜主，柔順以居，利得過倍。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>《說文》：「韓，乾也」，故震為韓、為長，兌為女，故曰長女。震為嫁、為東，兌為海，震為主，伏艮為家。巽為順、為利，二四正反巽，故曰倍。○三四兩句從宋元本，汲古作「多貌美好，宜家福壽」。過，汲古作十，亦依宋元本。</p><h3 id="需之旅" tabindex="-1">需之旅 <a class="header-anchor" href="#需之旅" aria-label="Permalink to “需之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>因禍受福，喜盈我室，所願必得。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。坎為禍，震為福喜，艮為室。○汲古多「先人後己」四字，在第三句，此從宋本。</p><h3 id="需之巽" tabindex="-1">需之巽 <a class="header-anchor" href="#需之巽" aria-label="Permalink to “需之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>晉平有疾，迎醫秦國。病乃大秘，分為兩豎。逃匿肓上，伏於膏下，和不能愈。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》為晉，坎平坎疾，故曰晉平有疾。醫醷同字，酒也。坎為酒，故借用以與象合。坎西故曰秦。艮為國也。坎為病、為隱伏，故曰病乃大秘。互艮為僮僕，故曰豎，正反艮故曰兩豎。坎為心、為膏肓，成十年杜註：「肓，鬲也，心下曰膏」。坎又為逃匿、為和，坎疾，故不愈。《左傳成十年》：「晉景公疾，求醫於秦，秦使醫緩為之，未至，公夢疾為二豎子，曰：『彼良醫也，懼傷我，焉逃之？』其一曰：『居肓之上、膏之下，若我何？』醫至，曰：『疾不可為也，在肓之上、膏之下，攻之不可，達之不及。』」○逃匿肓上、伏於膏下，宋元本作「逃匿膏肓」，雖簡捷似不如汲古文勢足，且韻協，故從汲古。</p><h3 id="需之兌" tabindex="-1">需之兌 <a class="header-anchor" href="#需之兌" aria-label="Permalink to “需之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>牡飛門啟，患憂大解。修福行善，不為身禍。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>牡門，牡也。兌牡在艮，艮伏不見，故曰飛。艮為門，震為啟，故曰牡飛門啟。艮中爻坎為憂患，震為解、為福，艮為身，坎為禍，震樂，故不為身禍。《漢書五行志》：「成帝元延元年，長安章城門門牡自亡」，或謂此事為焦氏所不及見。豈知京房死於元帝時，真不及見此事者，而房有厥妖、門牡自亡之占，可見此事古已有之，不始於成帝時。○牡，依汲古，宋元本皆作杜，非。</p><h3 id="需之渙" tabindex="-1">需之渙 <a class="header-anchor" href="#需之渙" aria-label="Permalink to “需之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>追亡逐北，至山而得。稚叔相呼，反其室廬。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>互震為追逐，艮止故至山而得。艮為叔，中爻正反震，故曰相呼。震為反，艮為室廬。○山，汲古作止，非。又汲古二三句倒置，亦非，依宋元本。</p><h3 id="需之節" tabindex="-1">需之節 <a class="header-anchor" href="#需之節" aria-label="Permalink to “需之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>鳥鳴葭端，一呼三顛。動搖東西，危慄不安，疾病無患。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為葦、為葭、為鳴，艮鳥在上，故曰葭端。坎數一，震數三，震為呼、為顛、為動搖，震東兌西，坎為慄、為疾病、為患，震樂，故無。</p><h3 id="需之中孚" tabindex="-1">需之中孚 <a class="header-anchor" href="#需之中孚" aria-label="Permalink to “需之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>龍化為虎，泰山之陽。眾多從者，莫敢敉藏。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為龍，艮為虎，震反為艮，故龍化為虎。艮山震東，故曰泰山。艮納丙，丙南，故曰為陽。震為從，正覆震，故曰眾。坎為藏，坎伏，故莫藏。○敉，從元本，撫也、愛也，宋本、汲古作救，義淺。</p><h3 id="需之小過" tabindex="-1">需之小過 <a class="header-anchor" href="#需之小過" aria-label="Permalink to “需之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>猋風阻越，車馳揭揭。棄古追思，失其和節，憂心惙惙。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>巽風，艮火炎上，故曰猋風。《爾雅》：「扶搖謂之猋」註：暴風從下上。又《月令》：「猋風暴雨總至。」註：迴風為猋。中爻正反巽，故曰猋風。越，散也、墜也，阻越，猶逾越也。《易林》用一字能含數卦象，此等雖《易》亦少也。震為越、為車、為馳。揭揭，馳貌。震為追，坎為思，坎為和、為失、為憂、為心，《詩檜風》：「匪風發兮，匪車偈兮；顧瞻周道，中心怛兮」，思，周道也。棄古追思者，言古周道滅絕，今追思之，正詩意也，或作棄名則違詩意矣。○猋，從宋元本，汲古作焱，猋，音標。焱，音艷，《說文》：「火華也」。阻越，各本皆訛忽起，古訛名，均依渙之乾宋本校。</p><h3 id="需之既濟" tabindex="-1">需之既濟 <a class="header-anchor" href="#需之既濟" aria-label="Permalink to “需之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>游居石門，祿安身全。受福西鄰，歸飲玉泉。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《需》象。乾為石、為門、為行，故曰游居石門。乾為福、為祿、為玉，坎為西鄰，兌口，故曰飲。石門，地名。《論語》：「子路宿於石門。」</p><h3 id="需之未濟" tabindex="-1">需之未濟 <a class="header-anchor" href="#需之未濟" aria-label="Permalink to “需之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>登高上山，見王自言。申理我讒，得職蒙恩。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>震為登，艮為高、為山，震為王、為言、為申，坎離皆上下兌口相背，故曰讒。艮為官，故曰得職。多用半象，《易林》於既、未濟通例也。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
